const {chromium}=require('playwright');(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:390,height:900}});await p.goto('file://'+process.cwd()+'/'+process.argv[2]);await p.waitForTimeout(300);
console.log(await p.evaluate(()=>{const tr=document.querySelector('.lb-tbl tbody tr');const cs=getComputedStyle(tr);return [cs.display,cs.gridTemplateColumns,cs.paddingLeft,...[...tr.children].map(td=>{const s=getComputedStyle(td);return s.display+' '+s.gridColumnStart+'/'+s.gridColumnEnd+' r'+s.gridRowStart+' pos='+s.position+' L'+Math.round(td.getBoundingClientRect().left)})]}));await b.close()})();
